\section{Introduction}

Mesh refinement is the engine of computational geometry and numerical PDE: a
domain is decomposed into simplices and the decomposition is iteratively refined by
inserting new vertices (``Steiner points'') until the simplices are small enough
for the accuracy demanded. The defining performance question is the \emph{rate} at
which the largest simplex shrinks. A scheme is useful when the worst diameter
contracts geometrically---by a fixed factor $1/\lambda < 1$ per round---so that
after $k$ rounds it is at most $(1/\lambda)^k$ times its initial value.

In the \emph{minicenter} family of schemes, the Steiner point of a simplex is the
center of its smallest enclosing ball. For a one-dimensional simplex (an edge), the
minicenter is exactly the midpoint and the contraction factor is exactly
$\lambda = 2$. The conjecture that minicenter refinement contracts the diameter by
a uniform factor $\lambda > 1$ in every dimension is, in full geometric generality,
open. Its \emph{metric backbone}---that a uniform per-step contraction forces
exponential decay---is a clean, complete theory.

This paper develops the realistic, \emph{noisy} extension. Practical refinement is
never exact: re-triangulation, neighbor displacement, and floating-point error
reinject a bounded perturbation at each step. We model this with an additive defect
$b \ge 0$ and study $d_{k+1} \le a d_k + b$. The conclusions are sharp and
practically important: contraction survives noise, and the price of noise is a
single computable resolution floor $L = b/(1-a)$.

\section{Definitions}

\begin{definition}[Inhomogeneous contraction process]\label{def:icp}
An \emph{inhomogeneous contraction process} consists of a sequence
$d : \NN \to \RR$ and constants $a, b \in \RR$ with
\[
0 \le a, \qquad a < 1, \qquad 0 \le b, \qquad \forall k,\ 0 \le d_k, \qquad
\forall k,\ d_{k+1} \le a\,d_k + b.
\]
Here $d_k$ is the maximum simplex diameter after $k$ rounds, $a$ is the geometric
contraction per round, and $b$ is the additive defect from Steiner-point insertion.
\end{definition}

\begin{definition}[Attractor radius]\label{def:L}
The \emph{attractor radius} (fixed point) is $L := b/(1-a)$. Since $a<1$ we have
$1-a>0$, so $L$ is well-defined; since $b \ge 0$, $L \ge 0$.
\end{definition}

\begin{definition}[Affine iteration]\label{def:aff}
For chosen $d_0 \ge 0$, the \emph{affine iteration} is the process satisfying the
exact recurrence $d_{k+1} = a\,d_k + b$. It is a concrete instance of
Definition~\ref{def:icp} (the inequality holds with equality) and serves as the
tightness witness.
\end{definition}

\begin{definition}[Homogeneous contraction process]\label{def:hom}
A \emph{homogeneous contraction process} consists of $d : \NN \to \RR$ and a factor
$\lambda > 1$ with $d_k \ge 0$ and $d_{k+1} \le (1/\lambda)\,d_k$. This is the
$b=0$, $a=1/\lambda$ specialization.
\end{definition}

\section{The fixed point}

\begin{lemma}[Fixed-point identity]\label{lem:fp}
$a\,L + b = L.$
\end{lemma}
\begin{proof}
Substitute $L = b/(1-a)$ and clear the positive denominator:
$a\cdot\frac{b}{1-a} + b = \frac{ab + b(1-a)}{1-a} = \frac{b}{1-a} = L.$
\end{proof}

\section{The closed-form bound}

\begin{theorem}[Closed-form upper bound]\label{thm:cf}
For every $k \in \NN$,
\[
d_k \;\le\; a^{k}\,d_0 \;+\; b\,\frac{1 - a^{k}}{1 - a}.
\]
\end{theorem}
\begin{proof}
Induction on $k$. For $k=0$ the right side equals $d_0$, an equality. Assuming the
bound at $k$, the contraction hypothesis and $a \ge 0$ give
\[
d_{k+1} \le a\,d_k + b \le a\Bigl(a^{k} d_0 + b\tfrac{1-a^{k}}{1-a}\Bigr) + b.
\]
Using $a(1-a^k) + (1-a) = 1 - a^{k+1}$ the right side equals
$a^{k+1} d_0 + b\frac{1 - a^{k+1}}{1-a}$.
\end{proof}

\begin{lemma}[Centering at the fixed point]\label{lem:center}
For every $k$,
$a^{k} d_0 + b\frac{1 - a^{k}}{1 - a} = a^{k}(d_0 - L) + L.$
\end{lemma}
\begin{proof}
$a^k(d_0 - L) + L = a^k d_0 + L(1 - a^k)$; substitute $L = b/(1-a)$.
\end{proof}

\begin{theorem}[Geometric decay of the transient]\label{thm:excess}
For every $k$, $\;d_k - L \le a^{k}(d_0 - L).$
\end{theorem}
\begin{proof}
Combine Theorem~\ref{thm:cf} with Lemma~\ref{lem:center} and subtract $L$.
\end{proof}

\section{Convergence of the bound and one-sided trapping}

\begin{theorem}[Convergence of the closed-form bound]\label{thm:tend}
$\displaystyle \lim_{k\to\infty}\Bigl(a^{k} d_0 + b\tfrac{1 - a^{k}}{1 - a}\Bigr) = L.$
\end{theorem}
\begin{proof}
Since $0 \le a < 1$, $a^k \to 0$; hence $a^k d_0 \to 0$ and
$b\frac{1-a^k}{1-a} \to \frac{b}{1-a} = L$.
\end{proof}

\begin{theorem}[Eventual trapping]\label{thm:trap}
For every $\varepsilon > 0$, eventually $d_k < L + \varepsilon$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:tend} the bound is eventually $< L+\varepsilon$; by
Theorem~\ref{thm:cf}, $d_k$ is dominated by that bound.
\end{proof}

\begin{corollary}[Explicit iteration count]\label{cor:N}
For every $\varepsilon > 0$ there exists $N$ with $d_k < L + \varepsilon$ for all
$k \ge N$.
\end{corollary}

\begin{remark}
The inequality model does not force $d_k \to L$: the sequence $d_k \equiv 0$
satisfies $0 \le a\cdot 0 + b$ for any $b \ge 0$ yet never reaches $L$ when $b>0$.
Only one-sided trapping in $[0,L+\varepsilon]$ is provable from the inequality.
\end{remark}

\section{Two-sided convergence under the exact recurrence}

\begin{theorem}[Genuine convergence and sharp rate]\label{thm:exact}
If $d_{k+1} = a\,d_k + b$ for all $k$, then
\[
|\,d_k - L\,| \le a^{k}\,|\,d_0 - L\,| \qquad\text{and}\qquad \lim_{k\to\infty} d_k = L.
\]
\end{theorem}
\begin{proof}
Subtracting $L = aL + b$ (Lemma~\ref{lem:fp}) from the exact recurrence gives
$d_{k+1} - L = a(d_k - L)$, so $d_k - L = a^k(d_0 - L)$ by induction. Take absolute
values for the rate; $a^k \to 0$ yields the limit.
\end{proof}

\section{Boundedness and bounded perturbation}

\begin{proposition}[Uniform band]\label{prop:band}
For every $k$, $d_k \le d_0 + L$; with $d_k \ge 0$, every iterate lies in
$[0, d_0 + L]$.
\end{proposition}
\begin{proof}
From Theorem~\ref{thm:excess}, $d_k \le L + a^k(d_0 - L)$. If $d_0 \ge L$ then
$a^k(d_0-L) \le d_0-L$, so $d_k \le d_0$; if $d_0 < L$ then $a^k(d_0-L) \le 0$, so
$d_k \le L$. In both cases $d_k \le d_0 + L$.
\end{proof}

\begin{proposition}[Bounded per-step perturbation]\label{prop:pert}
Each step perturbs the diameter by at most $b$: $d_{k+1} - a\,d_k \le b$.
\end{proposition}
\begin{proof}
Immediate from Definition~\ref{def:icp}.
\end{proof}

\section{The contraction-map picture}

Let $f(x) = a\,x + b$ on $\RR$.

\begin{proposition}[Contraction constant]\label{prop:contr}
For all $x,y$, $\dist(f(x),f(y)) = a\,\dist(x,y)$.
\end{proposition}
\begin{proof}
$f(x)-f(y) = a(x-y)$, and $a \ge 0$.
\end{proof}

\begin{proposition}[Fixed point]\label{prop:fix}
$f(L) = L$.
\end{proposition}
\begin{proof}
Lemma~\ref{lem:fp}: $f(L) = aL + b = L$.
\end{proof}

\begin{proposition}[Uniqueness]\label{prop:uniq}
$L$ is the unique fixed point of $f$.
\end{proposition}
\begin{proof}
$f(x)=x \Rightarrow (1-a)x = b \Rightarrow x = b/(1-a) = L$, since $1-a>0$.
\end{proof}

Since $0 \le a < 1$, $f$ is a Banach contraction with constant $a$; Propositions
\ref{prop:contr}--\ref{prop:uniq} re-derive convergence to $L$ metrically.

\section{Tightness}

\begin{theorem}[Tightness via the affine iteration]\label{thm:tight}
The affine iteration (Definition~\ref{def:aff}) satisfies $d_{k+1} = a d_k + b$
exactly; hence its closed form is $a^k d_0 + b(1-a^k)/(1-a)$ (equality in
Theorem~\ref{thm:cf}) and its limit is $L$ (Theorem~\ref{thm:exact}). The upper
bounds of Theorems~\ref{thm:cf}--\ref{thm:excess} are attained, and no scheme with
per-step defect $\ge b$ guarantees asymptotic diameter below $L = b/(1-a)$.
\end{theorem}

\section{The homogeneous base case}

\begin{theorem}[Noiseless exponential contraction]\label{thm:hom}
For a homogeneous contraction process, $d_k \le (1/\lambda)^k d_0$ and $d_k \to 0$.
\end{theorem}
\begin{proof}
Induction gives the bound; squeezing $0 \le d_k \le (1/\lambda)^k d_0$ with
$(1/\lambda)^k \to 0$ gives the limit. This is Theorems~\ref{thm:cf}--\ref{thm:excess}
at $b=0$ ($L=0$).
\end{proof}

\begin{theorem}[One-simplex minicenter is the midpoint]\label{thm:seg}
For an edge $[a,b]$ in a real normed space and $m=\tfrac12(a+b)$,
$\dist(a,m) = \dist(m,b) = \tfrac12\dist(a,b)$. Hence repeated edge bisection is a
homogeneous contraction process with $\lambda=2$ and $d_k = D/2^k$.
\end{theorem}
\begin{proof}
Direct computation with the midpoint and norm; the smallest enclosing ball of a
segment is centered at its midpoint, giving two equal half-length sub-edges.
\end{proof}

\section{Applications}

\begin{enumerate}
\item \textbf{Adaptive mesh refinement.} Imperfect Steiner placement still
contracts exponentially down to the floor $b/(1-a)$; halving $b$ halves the floor.
\item \textbf{Numerical linear algebra.} Linearly convergent solvers with per-step
round-off settle at a floor proportional to machine epsilon over $(1-a)$.
\item \textbf{Control / DSP.} A first-order IIR filter $x_{k+1} = a x_k + b$ is the
exact recurrence; $b/(1-a)$ is its steady-state value.
\item \textbf{Stochastic approximation / RL.} Contractive updates with bounded
noise hover in a ball of radius $\sim b/(1-a)$ about the target.
\end{enumerate}

\section{Discussion and future work}

Under any genuine contraction ($a<1$), bounded per-step noise costs only a finite,
computable floor $L = b/(1-a)$, and the transient above it decays at the same
geometric rate $a^k$ as in the noiseless case. The inequality/equality dichotomy
(one-sided trapping vs.\ two-sided convergence) is essential. Open geometric
directions concern the constant $a$ in higher dimensions: whether $d$-simplex
medial subdivision halves the diameter for all $d$ (known for $d=1,2$; the
$d\ge 3$ central pieces are the first obstruction), whether true minicenter
subdivision of a triangle contracts by $\lambda \ge \sqrt2$, and the sharpness of
the perturbed attractor as an exact min-max diameter.

